"""Task sets of the factory domain, generated by seeded scripts from a floor file (nothing is hand-picked): the standard set and the
messy-person set (the places' own names, aliases and zone names are what the person's wording is made from)."""
from __future__ import annotations

from .tasks_gen import generate_tasks
from .world import load_floor


def factory_tasks(floor: str, n: int, seed: int) -> list:
    w = load_floor(floor)
    objects = [{"id": o.id, "label": o.label, "at": o.at} for o in w.objects.values()
               if o.weight_kg <= w.payload_kg and not w.places[o.at].locked]
    places = [{"id": p.id, "name": p.name, "spoken": "the " + p.name} for p in w.places.values() if p.kind in ("surface", "bin") and p.slots > 0]
    return generate_tasks(objects, places, n, seed, spoken_all={p.id: "the " + p.name for p in w.places.values()})


def factory_messy_tasks(floor: str, n_per_policy: int, seed: int) -> list:
    """The messy-person suite (docs/EXPERIMENT_MESSY.md): the places' own names and aliases, and the zone name, are what the person's wording is made from."""
    from .messy import messy_tasks
    w = load_floor(floor)
    info = {p.id: {"names": [p.name] + list(p.aliases), "zone": p.zone.replace("_", " ")} for p in w.places.values()}
    objects = [{"id": o.id, "label": o.label, "at": o.at} for o in w.objects.values()
               if o.weight_kg <= w.payload_kg and not w.places[o.at].locked]
    places = [{"id": p.id, "name": p.name, "spoken": "the " + p.name} for p in w.places.values() if p.kind in ("surface", "bin") and p.slots > 0]
    return messy_tasks(objects, places, info, n_per_policy, seed, {p.id: "the " + p.name for p in w.places.values()})
